import samples from '../../data/sandbox/samples.json';

/**
 * View model for the synthetic sample shown on /data-sandbox and the homepage teaser.
 * The data file is generated by scripts/build-sandbox-samples.mjs from a pinned
 * data-sandbox checkout; nothing here invents a field or a figure.
 */

const SANDBOX_ORIGIN = 'https://data-sandbox.openfinance-os.org';

export type ViewKey = 'accounts' | 'balances' | 'transactions' | 'policies' | 'policy';

export interface Row {
  cells: string[];
  tone?: 'credit' | 'debit';
}

export interface Fact {
  label: string;
  value: string;
}

export interface SampleView {
  key: ViewKey;
  label: string;
  path: string;
  excerpt: string | null;
  watermark: string;
  json: string;
  columns?: string[];
  rows?: Row[];
  facts?: Fact[];
}

export interface SamplePersona {
  id: string;
  name: string;
  /** Short label for a tab: the part of the manifest name before the dash. */
  shortName: string;
  role: string;
  segment: string;
  domain: 'Banking' | 'Insurance';
  seed: number;
  profile: string;
  blurb: string;
  explorerUrl: string;
  views: SampleView[];
  highlight: { label: string; value: string; note: string };
}

type Money = { Amount: string; Currency: string };
// The fixtures are schema-shaped JSON; fields are read defensively because
// optional ones are absent on the Median profile.
type Loose = Record<string, any>;

const VIEW_LABELS: Record<ViewKey, string> = {
  accounts: 'Accounts',
  balances: 'Balances',
  transactions: 'Transactions',
  policies: 'Policies',
  policy: 'Policy detail',
};

/** One line per persona on what the example is good for. Editorial, not generated. */
const BLURBS: Record<string, string> = {
  salaried_expat_mid:
    'A salaried customer with a current account and a credit card. A baseline for affordability and budgeting ideas.',
  sme_cash_heavy:
    'A small retailer whose income arrives as cash deposits. Useful for testing how a service reads irregular inflows.',
  motor_comprehensive_mid:
    'A comprehensive motor policy with cover, excess, premium and claims history. A starting point for insurance comparison ideas.',
};

export function formatMoney(money: Money | undefined): string {
  if (!money) return 'Not provided';
  const value = Number(money.Amount);
  if (!Number.isFinite(value)) return `${money.Currency} ${money.Amount}`;
  return `${money.Currency} ${value.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

export function formatDay(iso: string | undefined): string {
  if (!iso) return 'Not provided';
  const date = new Date(iso.length === 10 ? `${iso}T00:00:00Z` : iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

/** PascalCase enum to words: "CurrentAccount" becomes "Current account". */
export function humanise(value: string | undefined): string {
  if (!value) return 'Not provided';
  if (value === value.toUpperCase()) return value;
  const words = value.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/**
 * Link into the full explorer. Persona, profile, seed and corpus always travel
 * together: the explorer treats the three as one bundle, and a persona opened
 * with another persona's seed is not a published fixture.
 */
export function explorerUrl(persona: string, profile: string, seed: number, corpus: string) {
  const query = new URLSearchParams({
    persona,
    lfi: profile,
    seed: String(seed),
    corpus,
  });
  return `${SANDBOX_ORIGIN}/src/index.html?${query}`;
}

function splitName(name: string): { shortName: string; role: string } {
  const [first, ...rest] = name.split(' — ');
  return { shortName: first, role: rest.join(' — ') || first };
}

function accountsView(data: Loose) {
  return {
    columns: ['Account', 'Type', 'Currency', 'IBAN', 'Status'],
    rows: (data.Account as Loose[]).map((account) => ({
      cells: [
        account.Nickname ?? humanise(account.AccountSubType),
        `${account.AccountType} · ${humanise(account.AccountSubType)}`,
        account.Currency,
        account.AccountIdentifiers?.[0]?.Identification ?? 'Not provided',
        account.Status,
      ],
    })),
  };
}

function balancesView(data: Loose) {
  return {
    columns: ['Balance type', 'Amount', 'Direction', 'As at'],
    rows: (data.Balance as Loose[]).map((balance) => ({
      cells: [
        humanise(balance.Type),
        formatMoney(balance.Amount),
        balance.CreditDebitIndicator,
        formatDay(balance.DateTime),
      ],
    })),
  };
}

function transactionsView(data: Loose) {
  return {
    columns: ['Booked', 'Description', 'Type', 'Amount'],
    rows: (data.Transaction as Loose[]).map((transaction) => {
      const credit = transaction.CreditDebitIndicator === 'Credit';
      return {
        tone: credit ? ('credit' as const) : ('debit' as const),
        cells: [
          formatDay(transaction.BookingDateTime),
          transaction.TransactionInformation ?? 'Not provided',
          humanise(transaction.TransactionType),
          `${credit ? '+' : '−'} ${formatMoney(transaction.Amount)}`,
        ],
      };
    }),
  };
}

function policiesView(data: Loose) {
  return {
    columns: ['Policy number', 'Status', 'Starts', 'Ends'],
    rows: (data.Policies as Loose[]).map((policy) => ({
      cells: [
        policy.PolicyNumber,
        policy.PolicyStatus,
        formatDay(policy.PolicyStartDate),
        formatDay(policy.PolicyEndDate),
      ],
    })),
  };
}

function policyView(data: Loose) {
  const policy: Loose = data.Product?.Policy ?? {};
  const vehicle: Loose = data.Product?.VehicleDetails ?? {};
  const claims: Loose | undefined = data.Claims?.Summary?.[0];
  const facts: Fact[] = [
    { label: 'Product', value: policy.ProductName ?? 'Not provided' },
    { label: 'Cover type', value: humanise(policy.TypeOfPolicy) },
    {
      label: 'Vehicle',
      value:
        [vehicle.ModelYear, vehicle.Make, vehicle.Model].filter(Boolean).join(' ') ||
        'Not provided',
    },
    { label: 'Vehicle valuation', value: formatMoney(policy.CarValuation) },
    { label: 'Policy excess', value: formatMoney(policy.PolicyExcess) },
    { label: 'Total premium', value: formatMoney(data.Premium?.TotalPremiumAmount) },
    { label: 'Payment', value: humanise(data.Premium?.PaymentFrequency) },
    {
      label: 'Claims',
      value: claims
        ? `${claims.Claims} in the last ${claims.NumberOfMonthsInPeriod} months`
        : 'Not provided',
    },
  ];
  return { facts };
}

const BUILDERS: Record<ViewKey, (data: Loose) => Partial<SampleView>> = {
  accounts: accountsView,
  balances: balancesView,
  transactions: transactionsView,
  policies: policiesView,
  policy: policyView,
};

function highlightFor(views: Record<string, Loose>): SamplePersona['highlight'] {
  if (views.balances) {
    const balance = views.balances.envelope.Data.Balance[0];
    return {
      label: humanise(balance.Type),
      value: formatMoney(balance.Amount),
      note: `As at ${formatDay(balance.DateTime)}, the fixture's reference date`,
    };
  }
  const data = views.policy.envelope.Data;
  return {
    label: 'Total premium',
    value: formatMoney(data.Premium?.TotalPremiumAmount),
    note: `${data.Product.Policy.ProductName}, paid ${humanise(data.Premium?.PaymentFrequency).toLowerCase()}`,
  };
}

export const sampleSource = samples.source;

export const samplePersonas: SamplePersona[] = samples.personas.map((persona) => {
  const rawViews = persona.views as unknown as Record<string, Loose>;
  const views = (Object.keys(VIEW_LABELS) as ViewKey[])
    .filter((key) => rawViews[key])
    .map((key) => {
      const raw = rawViews[key];
      return {
        key,
        label: VIEW_LABELS[key],
        path: raw.path as string,
        excerpt: raw.excerpt as string | null,
        watermark: raw.envelope._watermark as string,
        json: JSON.stringify(raw.envelope, null, 2),
        ...BUILDERS[key](raw.envelope.Data),
      } satisfies SampleView;
    });

  return {
    id: persona.id,
    name: persona.name,
    ...splitName(persona.name),
    segment: persona.segment,
    domain: persona.domains.includes('insurance') ? 'Insurance' : 'Banking',
    seed: persona.seed,
    profile: persona.lfi,
    blurb: BLURBS[persona.id] ?? '',
    explorerUrl: explorerUrl(persona.id, persona.lfi, persona.seed, samples.source.corpusVersion),
    views,
    highlight: highlightFor(rawViews),
  };
});
